import{_ as t,o as g,c as h,a3 as c}from"./chunks/framework.DX_KL3e0.js";const o="/help/screenshots/cham-cong/tong-quan.png",i="/help/screenshots/cham-cong/diem-danh.png",a="/help/screenshots/cham-cong/bang-thang.png",r="/help/screenshots/cham-cong/nghi-phep.png",y=JSON.parse('{"title":"Dữ liệu Chấm công","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/cham-cong.md","filePath":"chuc-nang/cham-cong.md","lastUpdated":1783009205000}'),s={name:"chuc-nang/cham-cong.md"};function u(l,n,m,e,p,d){return g(),h("div",null,[...n[0]||(n[0]=[c('<h1 id="du-lieu-cham-cong" tabindex="-1">Dữ liệu Chấm công <a class="header-anchor" href="#du-lieu-cham-cong" aria-label="Permalink to &quot;Dữ liệu Chấm công&quot;">​</a></h1><p>Module <strong>Dữ Liệu Chấm Công</strong> là trung tâm điểm danh và quản lý công của nhân sự: chấm công vào/ra trên điện thoại, tra cứu bảng công cá nhân theo tháng, đề xuất bù công — tăng ca, xin nghỉ phép, xem bảng công đội ngũ và theo dõi chuyên cần.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tra-cuu/du-lieu-cong</code> (menu <strong>Dữ Liệu Chấm Công</strong>, luôn hiện cho mọi người dùng).</li><li><strong>Ai dùng được:</strong> Tất cả nhân sự (chấm công, tra cứu, nghỉ phép). Một số phân hệ giới hạn theo vai trò — xem bảng bên dưới.</li><li><strong>Phân hệ:</strong> Chấm Công · Tra Cứu Dữ Liệu Công · Nghỉ Phép · Bảng Công (Quản Lý) · Hồ Sơ Chuyên Cần (Quản Lý) · Tổng Hợp (HCNS) · Cấu Hình Máy (Admin).</li></ul></div><div class="tip custom-block"><p class="custom-block-title">🆕 Thay đổi quan trọng</p><p>Bảng công <strong>không còn nộp/duyệt thủ công</strong>. Nhân viên chỉ cần chấm công đầy đủ; hệ thống <strong>tự chốt &amp; gửi bảng công</strong> về Bộ Phận Chấm Công khi tới hạn. Quản lý xem bảng công đội ngũ ở phân hệ <strong>Bảng Công</strong> (chỉ xem).</p></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+o+'" alt="Trang Dữ liệu Chấm công"></p><p>Trang chính là lưới các thẻ dẫn tới từng phân hệ. Thẻ nào hiển thị tùy theo quyền của bạn.</p><table tabindex="0"><thead><tr><th>Phân hệ</th><th>Đường dẫn</th><th>Dành cho</th></tr></thead><tbody><tr><td><strong>Chấm Công</strong></td><td><code>/tra-cuu/du-lieu-cong/cham-cong</code></td><td>Mọi người — điểm danh vào/ra</td></tr><tr><td><strong>Tra Cứu Dữ Liệu Công</strong></td><td><code>/tra-cuu/du-lieu-cong/tra-cuu</code></td><td>Mọi người — xem bảng công cá nhân</td></tr><tr><td><strong>Nghỉ Phép</strong></td><td><code>/tra-cuu/du-lieu-cong/nghi-phep</code></td><td>Mọi người — xin nghỉ, xem quỹ phép</td></tr><tr><td><strong>Bảng Công</strong></td><td><code>/tra-cuu/du-lieu-cong/bang-cong</code></td><td>Quản Lý — xem bảng công đội ngũ (chỉ xem)</td></tr><tr><td><strong>Hồ Sơ Chuyên Cần</strong></td><td><code>/tra-cuu/du-lieu-cong/chuyen-can</code></td><td>Quản Lý — chỉ số đúng giờ/đi trễ/về sớm, điểm chuyên cần</td></tr><tr><td><strong>Tổng Hợp Dữ Liệu Công</strong></td><td><code>/tra-cuu/du-lieu-cong/tong-hop</code></td><td>Phòng HCNS — tổng hợp toàn công ty</td></tr><tr><td><strong>Cấu Hình Máy Chấm Công</strong></td><td><code>/tra-cuu/du-lieu-cong/cau-hinh</code></td><td>Admin — gán mã máy vân tay</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Cấu hình Quy Tắc Chấm Công</p><p>Ngoài các phân hệ trên, Super Admin có trang <strong>Cấu Hình Máy Chấm Công</strong> kèm <strong>Quy Tắc Chấm Công</strong> (giờ làm theo tuần, kỳ công, hạn tự gửi bảng công, khung tăng ca…). Xem <a href="/help/quan-tri/cau-hinh-cham-cong.html">Cấu hình Chấm công</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Cấu hình thuộc Quản trị</p><p>Phần <strong>Cấu Hình Máy Chấm Công</strong> và <strong>Cấu Hình Loại Phép</strong> là tác vụ quản trị (gán mã máy vân tay, khai báo loại phép, chính sách cộng phép năm). Tài liệu này chỉ hướng dẫn các thao tác nghiệp vụ thường ngày; phần thiết lập do Admin thực hiện.</p></div><h2 id="_1-cham-cong-vao-ra" tabindex="-1">1. Chấm công vào / ra <a class="header-anchor" href="#_1-cham-cong-vao-ra" aria-label="Permalink to &quot;1. Chấm công vào / ra&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Ai dùng cách này?</p><p><strong>Đa số nhân viên chấm công bằng máy vân tay</strong> tại văn phòng (dữ liệu tự đẩy về — xem mục <em>Tra cứu dữ liệu công</em>). Phần <strong>Chấm Công trên điện thoại</strong> dưới đây chỉ dành cho <strong>một số bộ phận đặc thù</strong>.</p></div><p>Trang <strong>Chấm Công</strong> dùng để điểm danh trực tiếp trên điện thoại. Hệ thống yêu cầu <strong>bắt buộc cả ảnh xác nhận và vị trí GPS</strong> mới cho chấm.</p><p><img src="'+i+'" alt="Màn hình chấm công vào/ra: đồng hồ, GPS, ảnh xác nhận"></p><p><strong>Các bước chấm công:</strong></p><ol><li>Mở <strong>Chấm Công</strong>. Đồng hồ hiển thị thời gian hiện tại, hai ô <strong>Giờ Vào</strong> / <strong>Giờ Ra</strong> cho biết tình trạng hôm nay.</li><li>Bật định vị (GPS) — ô <strong>Vị Trí (GPS)</strong> chuyển xanh khi lấy được tọa độ. Nếu chưa có, bấm biểu tượng làm mới để thử lại.</li><li>Bấm <strong>Chụp ảnh xác nhận</strong> — camera trước mở ra để chụp selfie. Ảnh được tự động đóng dấu thời gian và toạ độ GPS.</li><li>Bấm nút <strong>Điểm Danh VÀO</strong> (đầu ca) hoặc <strong>Điểm Danh RA</strong> (cuối ca). Hệ thống tự gợi ý nút phù hợp dựa trên trạng thái và giờ hiện tại.</li><li>Sau khi thành công, một thông báo Telegram được gửi ngay để xác nhận.</li></ol><div class="warning custom-block"><p class="custom-block-title">Bắt buộc ảnh + GPS</p><p>Thiếu ảnh hoặc thiếu GPS sẽ không chấm được. Trên Safari iPhone/iPad, vào <em>Cài đặt → Safari → Vị trí</em> và chọn &quot;Hỏi&quot; hoặc &quot;Cho phép&quot;. GPS chỉ hoạt động trên kết nối HTTPS.</p></div><div class="tip custom-block"><p class="custom-block-title">Đề phòng nhầm lẫn</p><ul><li>Nếu sự kiện gần nhất đã là &quot;Vào&quot;, hệ thống sẽ hỏi lại trước khi cho chấm Vào lần hai.</li><li>Nếu hôm qua chấm Vào mà quên chấm Ra, trang sẽ cảnh báo và nhắc liên hệ quản lý để bổ sung.</li><li>Vị trí lệch hơn 50km so với lần chấm trước sẽ hiện cảnh báo &quot;vị trí bất thường&quot;.</li><li>Mọi lần bấm đều được ghi lại — quản lý có thể kiểm tra, không lo nhấn nhầm.</li></ul></div><p>Phần <strong>Lịch sử hôm nay</strong> liệt kê tất cả lần chấm trong ngày, kèm nhãn nguồn: <strong>App</strong> (điện thoại) hoặc <strong>Máy</strong> (máy vân tay đẩy dữ liệu về).</p><h2 id="_2-tra-cuu-du-lieu-cong" tabindex="-1">2. Tra cứu dữ liệu công <a class="header-anchor" href="#_2-tra-cuu-du-lieu-cong" aria-label="Permalink to &quot;2. Tra cứu dữ liệu công&quot;">​</a></h2><p>Trang <strong>Tra Cứu Dữ Liệu Công</strong> cho xem lại toàn bộ chấm công của bạn theo tháng và khai bù công / tăng ca cho ngày thiếu.</p><p><img src="'+a+'" alt="Tra cứu dữ liệu công theo tháng — tab Tổng Hợp / App / Vân Tay"></p><ul><li><strong>Chọn tháng:</strong> dùng mũi tên trái/phải để xem các tháng khác nhau.</li><li><strong>Thẻ thống kê:</strong> số ngày có chấm công, tổng giờ làm, tổng giờ tăng ca đã duyệt.</li><li><strong>Ba tab nguồn:</strong> <strong>Tổng Hợp</strong> (App + Máy), <strong>App</strong> (chấm qua ứng dụng), <strong>Vân Tay</strong> (máy chấm công).</li><li><strong>Realtime:</strong> khi đang xem tháng hiện tại, dữ liệu tự cập nhật khi có lần chấm mới từ máy vân tay (chấm đỏ/xanh &quot;Realtime&quot;). Nút <strong>Làm mới</strong> để tải lại thủ công.</li><li><strong>Xuất CSV:</strong> bấm <strong>CSV</strong> để tải file chi tiết của tháng.</li></ul><h3 id="bang-cong-tu-gui-—-khong-can-nop-thu-cong" tabindex="-1">Bảng công tự gửi — không cần nộp thủ công <a class="header-anchor" href="#bang-cong-tu-gui-—-khong-can-nop-thu-cong" aria-label="Permalink to &quot;Bảng công tự gửi — không cần nộp thủ công&quot;">​</a></h3><p>Bạn <strong>không cần bấm nộp</strong> bảng công nữa. Việc của bạn là <strong>chấm công đầy đủ</strong> trong kỳ và khai bù công / tăng ca cho những ngày thiếu (nếu có). Khi tới <strong>thời gian tự gửi</strong> do công ty cấu hình, hệ thống <strong>tự chốt và gửi bảng công</strong> của kỳ về Bộ Phận Chấm Công.</p><div class="tip custom-block"><p class="custom-block-title">Kiểm tra trước hạn</p><p>Trước thời điểm tự gửi, hãy rà lại tháng: ngày nào thiếu chấm thì khai <strong>Bù Công</strong>, làm thêm giờ thì khai <strong>Tăng Ca</strong> — vì sau khi bảng công được gửi, số liệu đã chốt. Mốc thời gian tự gửi do Super Admin cấu hình theo từng công ty (xem <a href="/help/quan-tri/cau-hinh-cham-cong.html">Cấu hình Chấm công</a>).</p></div><h2 id="_3-bu-cong-va-tang-ca" tabindex="-1">3. Bù công và tăng ca <a class="header-anchor" href="#_3-bu-cong-va-tang-ca" aria-label="Permalink to &quot;3. Bù công và tăng ca&quot;">​</a></h2><p>Ngay trong bảng công tháng (trang Tra Cứu), mỗi ngày có nút để đề xuất <strong>Bù Công</strong> hoặc khai báo <strong>Tăng Ca</strong>. Các đề xuất này gửi tới quản lý và chỉ có hiệu lực sau khi được duyệt.</p><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Cửa sổ <strong>Đề Xuất Bù Công</strong> (chọn chế độ, giờ vào/ra, lý do) và <strong>Khai Báo Tăng Ca</strong> (giờ bắt đầu/kết thúc, kết quả tính khung tối/đêm). <em>(Ảnh sẽ được bổ sung.)</em></p></div><h3 id="đe-xuat-bu-cong" tabindex="-1">Đề xuất bù công <a class="header-anchor" href="#đe-xuat-bu-cong" aria-label="Permalink to &quot;Đề xuất bù công&quot;">​</a></h3><p>Bấm <strong>Bù Công</strong> trên ngày tương ứng, chọn một trong các chế độ:</p><table tabindex="0"><thead><tr><th>Chế độ</th><th>Dùng khi</th></tr></thead><tbody><tr><td><strong>Bù công (chấm thiếu giờ)</strong></td><td>Quên hoặc thiếu chấm — đề xuất giờ vào &amp; giờ ra</td></tr><tr><td><strong>Công tác</strong></td><td>Đi công tác — tính 1 ngày công đầy đủ</td></tr><tr><td><strong>Làm việc tại nhà (WFH)</strong></td><td>Làm tại nhà — tính 1 ngày công đầy đủ</td></tr><tr><td><strong>Làm theo ca</strong></td><td>Làm theo ca — tính 1 ngày công đầy đủ</td></tr></tbody></table><p>Nhập <strong>lý do</strong> rồi bấm <strong>Gửi Yêu Cầu</strong>. Với ba chế độ Công tác / WFH / Làm theo ca, hệ thống tự tính 1 ngày công đầy đủ nên không cần nhập giờ.</p><h3 id="khai-bao-tang-ca" tabindex="-1">Khai báo tăng ca <a class="header-anchor" href="#khai-bao-tang-ca" aria-label="Permalink to &quot;Khai báo tăng ca&quot;">​</a></h3><p>Bấm nút tăng ca trên ngày tương ứng, chọn <strong>giờ bắt đầu</strong> và <strong>giờ kết thúc</strong>. Hệ thống tự tính theo khung:</p><ul><li>🌆 <strong>Khung tối:</strong> 17:30 – 22:00</li><li>🌙 <strong>Khung đêm:</strong> 22:00 – 07:00 (qua ngày hôm sau sẽ hiện nhãn &quot;+1 ngày&quot;)</li></ul><p>Nhập lý do (tùy chọn) rồi bấm <strong>Gửi Khai Báo</strong>. Khai báo đã được duyệt hoặc từ chối chuyển sang chế độ chỉ xem.</p><h2 id="_4-nghi-phep" tabindex="-1">4. Nghỉ phép <a class="header-anchor" href="#_4-nghi-phep" aria-label="Permalink to &quot;4. Nghỉ phép&quot;">​</a></h2><p>Trang <strong>Nghỉ Phép</strong> cho theo dõi quỹ phép năm và tạo đơn xin nghỉ.</p><p><img src="'+r+'" alt="Nghỉ phép — quỹ phép năm và đơn của tôi"></p><p>Phần trên hiển thị <strong>quỹ phép năm</strong>: số ngày còn lại, đã được cộng trong năm, đã nghỉ — kèm chi tiết theo từng loại phép. Có thể chọn năm ở góc phải. Bên dưới là danh sách <strong>Đơn nghỉ phép của tôi</strong> với trạng thái <em>Chờ duyệt · Đã duyệt · Từ chối · Đã hủy</em>.</p><h3 id="tao-đon-nghi-phep" tabindex="-1">Tạo đơn nghỉ phép <a class="header-anchor" href="#tao-đon-nghi-phep" aria-label="Permalink to &quot;Tạo đơn nghỉ phép&quot;">​</a></h3><ol><li>Bấm <strong>Tạo Nghỉ Phép</strong>.</li><li>Chọn <strong>loại phép</strong> — mỗi loại hiển thị mô tả, hình thức trả lương (công ty / BHXH / không lương), giới hạn ngày và phép năm còn lại (với loại trừ vào quỹ phép). Danh sách loại phép tự lọc theo <strong>công ty của bạn</strong>: loại dùng chung toàn hệ thống và loại riêng dành cho công ty bạn.</li><li>Chọn <strong>hình thức nghỉ</strong>: <strong>Theo ngày</strong> (chọn từ ngày → đến ngày) hoặc <strong>Theo giờ</strong> (chọn ngày, giờ bắt đầu, giờ kết thúc). Một số loại phép chỉ cho nghỉ trọn ngày. <ul><li>🆕 <strong>Nghỉ nửa buổi:</strong> ở hình thức <em>Theo giờ</em> có 2 nút chọn nhanh <strong>Nghỉ buổi sáng</strong> / <strong>Nghỉ buổi chiều</strong> — tự điền khung giờ buổi sáng/chiều theo cấu hình công ty (thường tính 0.5 ngày công), không cần nhập giờ tay.</li></ul></li><li>Xem <strong>dòng xem trước</strong> số ngày công bị trừ (nghỉ theo ngày đã tự bỏ Chủ Nhật và ngày lễ).</li><li>Nhập <strong>lý do</strong> rồi bấm <strong>Gửi đơn</strong>. Đơn được gửi tới quản lý trực tiếp xét duyệt.</li></ol><div class="tip custom-block"><p class="custom-block-title">Hủy đơn</p><p>Đơn đang <strong>chờ duyệt</strong> có thể hủy. Đơn đã duyệt vẫn hủy được nếu ngày bắt đầu nằm ở tương lai.</p></div><h2 id="_5-bang-cong-—-xem-bang-cong-đoi-ngu-quan-ly" tabindex="-1">5. Bảng Công — xem bảng công đội ngũ (Quản Lý) <a class="header-anchor" href="#_5-bang-cong-—-xem-bang-cong-đoi-ngu-quan-ly" aria-label="Permalink to &quot;5. Bảng Công — xem bảng công đội ngũ (Quản Lý)&quot;">​</a></h2><p>Trang <strong>Bảng Công</strong> cho quản lý <strong>xem</strong> (không duyệt) bảng công của nhân sự trong phạm vi quản lý, <strong>nhóm theo Công Ty → Phòng Ban</strong> giống trang Tổng Hợp.</p><ol><li>Chọn tháng cần xem bằng mũi tên trái/phải.</li><li>Dữ liệu hiển thị theo cây <strong>Công Ty → Phòng Ban</strong>; mỗi phòng ban có quản lý (biểu tượng vương miện) ở đầu, kèm số ngày/giờ và trạng thái đã gửi.</li><li>Bấm vào một nhân viên để <strong>xem chi tiết chấm công theo từng ngày</strong> (giờ vào/ra, nguồn App/Máy, GPS…).</li><li>Dùng ô <strong>tìm kiếm theo tên</strong> (không cần dấu) và các bộ lọc <strong>Công ty / Phòng ban / Trạng thái</strong> để khoanh vùng nhanh.</li></ol><div class="info custom-block"><p class="custom-block-title">Phạm vi theo vai trò</p><ul><li><strong>Người dùng:</strong> chỉ thấy bảng công của chính mình.</li><li><strong>Quản lý:</strong> thấy bản thân + toàn bộ cấp dưới (đệ quy) trong công ty.</li><li><strong>Admin:</strong> toàn bộ công ty đang làm việc.</li><li><strong>Super Admin:</strong> toàn hệ thống (mọi công ty).</li></ul><p>Đây là <strong>chế độ chỉ xem</strong> — bảng công tự gửi về Bộ Phận Chấm Công khi tới hạn, không có thao tác duyệt/từ chối. Việc duyệt <strong>Bù Công / Tăng Ca / Nghỉ Phép</strong> vẫn ở <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu → Duyệt Công</a>.</p></div><h2 id="_5b-ho-so-chuyen-can-quan-ly" tabindex="-1">5b. Hồ Sơ Chuyên Cần (Quản Lý) <a class="header-anchor" href="#_5b-ho-so-chuyen-can-quan-ly" aria-label="Permalink to &quot;5b. Hồ Sơ Chuyên Cần (Quản Lý)&quot;">​</a></h2><p>Trang <strong>Hồ Sơ Chuyên Cần</strong> tổng hợp chỉ số chuyên cần của từng nhân sự trong phạm vi quản lý: <strong>đúng giờ, đi trễ, về sớm, quên chấm, vắng, nghỉ phép theo loại</strong> và <strong>điểm &amp; xếp loại</strong> chuyên cần.</p><ol><li>Chọn khoảng thời gian bằng preset <strong>Tháng này · Tháng trước · Quý này · Năm nay · Tùy chỉnh</strong> (hoặc nhập <em>Từ ngày / Đến ngày</em>).</li><li>Xem bảng chỉ số từng người; tìm kiếm theo tên và lọc theo <strong>Công ty / Phòng ban / Xếp loại</strong>, sắp xếp theo điểm/đi trễ/vắng…</li><li>Bấm vào một người để xem <strong>chi tiết theo ngày</strong> (đích danh ngày đi trễ / về sớm / vắng / nghỉ phép).</li></ol><div class="tip custom-block"><p class="custom-block-title">Đi trễ / về sớm tính theo giờ làm từng ngày</p><p>Chỉ số đi trễ / về sớm được tính theo <strong>giờ ca của chính ngày đó</strong> trong <em>Quy Tắc Chấm Công</em> (ví dụ Thứ 7 làm nửa buổi sẽ tính đúng theo khung nửa buổi). Có thể bật/tắt hiển thị hồ sơ chuyên cần cho từng người.</p></div><h2 id="_6-tong-hop-du-lieu-cong-hcns" tabindex="-1">6. Tổng hợp dữ liệu công (HCNS) <a class="header-anchor" href="#_6-tong-hop-du-lieu-cong-hcns" aria-label="Permalink to &quot;6. Tổng hợp dữ liệu công (HCNS)&quot;">​</a></h2><p>Trang <strong>Tổng Hợp Dữ Liệu Công</strong> dành cho Phòng Hành Chính Nhân Sự tiếp nhận bảng công từ các quản lý gửi về, nhóm theo công ty → phòng ban, cảnh báo bảng công bất thường (số ngày quá thấp/quá cao), ghi chú, khóa bảng công và xuất Excel toàn công ty.</p><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Màn hình <strong>Tổng Hợp Dữ Liệu Công</strong>: cây công ty/phòng ban, trạng thái bảng công, công cụ chọn nhiều và xuất Excel. <em>(Ảnh sẽ được bổ sung.)</em></p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Tôi chấm bằng máy vân tay, sao trên app không thấy giờ Vào?</strong> Dữ liệu máy vân tay được đẩy về định kỳ. Trang Chấm Công tự làm mới mỗi 15 giây và trang Tra Cứu cập nhật realtime. Nếu chấm bằng máy rồi, khi dùng app hãy chọn đúng <strong>Điểm Danh RA</strong>.</p><p><strong>Không chấm công được vì không lấy được GPS?</strong> GPS cần kết nối HTTPS và quyền truy cập vị trí. Kiểm tra cài đặt trình duyệt (đặc biệt Safari iOS) rồi bấm làm mới GPS.</p><p><strong>Bù công / tăng ca tôi gửi bao giờ có hiệu lực?</strong> Sau khi quản lý duyệt tại <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu → Duyệt Công</a>, dữ liệu công sẽ tự cập nhật.</p><p><strong>Tôi có phải tự nộp bảng công không?</strong> Không. Bảng công <strong>tự chốt và gửi</strong> về Bộ Phận Chấm Công khi tới thời gian cấu hình của công ty. Bạn chỉ cần chấm công đầy đủ và khai bù công / tăng ca cho ngày thiếu <strong>trước</strong> thời điểm tự gửi.</p><p><strong>Sau khi bảng công đã gửi tôi phát hiện sai sót thì sao?</strong> Số liệu đã chốt khi gửi. Hãy liên hệ quản lý hoặc Phòng HCNS để được xử lý.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu</a> · <a href="/help/chuc-nang/tra-cuu.html">Tra cứu</a> · <a href="/help/chuc-nang/ho-so-cua-toi.html">Hồ sơ của tôi</a></p>',63)])])}const C=t(s,[["render",u]]);export{y as __pageData,C as default};
